/**
 * RADRAFT — SAVE APPROVAL DECISION
 * Workflow 4 — Split-workflow compatible
 *
 * No dependency on De-identification or
 * Re-identification nodes.
 */

const source = $('Data from Workflow 4').first().json;
const raw = $input.first().json;
const data = raw.data ?? raw;

// 1. Verify approval.
const rawDecision = String(
  data['Doctor decision'] ??
  data.decision ??
  ''
).trim();

const decision = rawDecision
  .replace(/[^\p{L}\s]/gu, '')
  .trim()
  .toLowerCase();

if (!['approve', 'approved'].includes(decision)) {
  throw new Error(
    `APPROVAL_ERROR: Invalid decision: ${rawDecision}`
  );
}

// 2. Read executed report-version nodes.
function readNode(name) {
  try {
    if (!$(name).isExecuted) return null;

    const items = $(name).all();
    return items.length
      ? items[items.length - 1].json
      : null;
  } catch {
    return null;
  }
}

// 3. Find the latest report.
// Use source data if no edits have occurred.
const candidates = [
  {
    name: 'Save Repeat Version',
    data: readNode('Save Repeat Version')
  },
  {
    name: 'Save New Report Version',
    data: readNode('Save New Report Version')
  },
  {
    name: 'Data from Workflow 4',
    data: source
  }
];

let selected = null;
let approvedReport = null;

for (const candidate of candidates) {
  if (!candidate.data) continue;

  const report = [
    candidate.data.current_report,
    candidate.data.approved_report,
    candidate.data.draft_report,
    candidate.data.final_report,
    candidate.data.report,
    candidate.data.output
  ].find(value =>
    typeof value === 'string' &&
    value.trim()
  );

  if (report) {
    selected = candidate;
    approvedReport = report;
    break;
  }
}

if (!approvedReport) {
  throw new Error(
    'APPROVAL_ERROR: No report found. Check Data from Workflow 4.'
  );
}

// 4. Obtain Telegram chat ID.
const chatId =
  selected.data.chat_id ??
  source.chat_id ??
  null;

if (chatId == null || chatId === '') {
  throw new Error('APPROVAL_ERROR: Missing chat ID.');
}

// 5. Preserve actual approval timestamp.
const approvedAt =
  data.respondedAt ??
  data.approved_at ??
  null;

if (
  !approvedAt ||
  Number.isNaN(Date.parse(approvedAt))
) {
  throw new Error(
    'APPROVAL_ERROR: Invalid approval timestamp.'
  );
}

// 6. Preserve report version.
const version = Number(
  selected.data.version ??
  source.version ??
  1
);

if (!Number.isInteger(version) || version < 1) {
  throw new Error(
    'APPROVAL_ERROR: Invalid version.'
  );
}

// 7. Return approved report.
return [{
  json: {
    chat_id: String(chatId),

    current_report: approvedReport,
    approved_report: approvedReport,

    doctor_name:
      source.doctor_name ?? null,

    patient_metadata_mapping:
      source.patient_metadata_mapping ?? {},

    patient_metadata_rest:
      source.patient_metadata_rest ?? {},

    report_id:
      source.report_id ?? null,

    session_id:
      source.session_id ?? null,

    version,
    approved_at: approvedAt,
    status: 'approved',

    report_source: selected.name
  }
}];

/**
 * RADRAFT — PREPARE EDITOR INPUT
 * Compatible with the split-workflow architecture.
 *
 * Mode: Run Once for All Items
 */

const source = $('Data from Workflow 4').first().json;

const raw = $input.first().json;
const data = raw.data ?? raw;

// 1. Get doctor's requested edits.
let feedback =
  data['Describe your requested edits'] ??
  data['Describe your requested adjustments'] ??
  data.text ??
  raw.text ??
  '';

if (!String(feedback).trim()) {
  const fallback = Object.entries(data).find(
    ([key, value]) =>
      key !== 'respondedAt' &&
      typeof value === 'string' &&
      value.trim()
  );

  if (fallback) feedback = fallback[1];
}

feedback = String(feedback).trim();

if (!feedback) {
  throw new Error('Doctor feedback is empty.');
}

// 2. Get latest report from available workflow outputs.
const candidates = [
  source.current_report,
  source.final_report,
  source.draft_report,
  source.report,
  source.output
];

const currentReport = candidates.find(
  value =>
    typeof value === 'string' &&
    value.trim()
);

if (!currentReport) {
  throw new Error(
    'No report found in Workflow 4 input.'
  );
}

// 3. Preserve session information.
const chatId = source.chat_id ?? null;

const version = Number(source.version ?? 1);

// 4. Return editor input.
return [{
  json: {
    chat_id: chatId !== null
      ? String(chatId)
      : null,

    current_report: currentReport,

    original_report:
      source.original_report ??
      source.draft_report ??
      currentReport,

    doctor_feedback: feedback,

    version,

    responded_at:
      data.respondedAt ?? null,

    doctor_name:
      source.doctor_name ?? null,

    session_id:
      source.session_id ?? null,

    report_id:
      source.report_id ?? null
  }
}];

/**
 * RADRAFT — REGEX DETECT 2
 * PHI detection for doctor-requested report revisions.
 *
 * Input: Prepare Editor Input
 *
 * Output:
 *   request_id
 *   text
 *   spans
 *
 * Mode: Run Once for All Items
 */

const patterns = {
  SSN: /\b\d{3}-\d{2}-\d{4}\b/g,
  PHONE_EG: /\b(?:\+?20[ -]?|0)1[0125]\d{8}\b/g,
  PHONE_INTL: /\b(?:\+?\d{1,3}[ -]?)?\(?\d{3}\)?[ -]?\d{3}[ -]?\d{4}\b/g,
  NATIONAL_ID_EG: /\b[23]\d{13}\b/g,
  EMAIL: /\b[\w.%+-]+@[\w.-]+\.[A-Za-z]{2,}\b/g,
  MRN: /\bMRN[:# ]?\s?\d{6,10}\b/gi,
  DATE: /\b\d{1,2}[/-]\d{1,2}[/-]\d{2,4}\b/g,
  IP: /\b(?:\d{1,3}\.){3}\d{1,3}\b/g,
  URL: /\bhttps?:\/\/[^\s]+/g,
  ACCOUNT: /\bACCT[:# ]?\s?\d{6,12}\b/gi
};

const output = [];

for (const item of $input.all()) {

  const json = item.json;

  const currentReport = String(
    json.current_report ?? ''
  );

  const doctorFeedback = String(
    json.doctor_feedback ?? ''
  );

  if (!currentReport.trim()) {
    throw new Error(
      'REGEX_DETECT_2: Current report is missing.'
    );
  }

  if (!doctorFeedback.trim()) {
    throw new Error(
      'REGEX_DETECT_2: Doctor feedback is missing.'
    );
  }

  // Combine the report and requested edits.
  // Both must pass through PHI detection.
  const text = [
    'CURRENT REPORT:',
    currentReport,
    '',
    'DOCTOR REQUESTED EDITS:',
    doctorFeedback
  ].join('\n');

  const spans = [];

  for (const [type, pattern] of Object.entries(patterns)) {

    const regex = new RegExp(
      pattern.source,
      pattern.flags
    );

    for (const match of text.matchAll(regex)) {
      spans.push({
        type,
        start: match.index,
        end: match.index + match[0].length,
        value: match[0],
        source: 'regex'
      });
    }
  }

  spans.sort((a, b) =>
    a.start - b.start ||
    b.end - a.end
  );

  output.push({
    json: {
      request_id: String(
        json.request_id ?? $execution.id
      ),
      text,
      spans,
      chat_id: json.chat_id ?? null,
      version: json.version ?? 1
    }
  });
}

return output;

/**
 * RADRAFT — DE-IDENTIFY 2
 * Doctor-requested report adjustments
 *
 * Input:
 *   Regex detect 2
 *   Presidio analyze 2
 *   Prepare Editor Input
 *
 * Output:
 *   userPrompt
 *   current_report
 *   original_report
 *   doctor_feedback
 *   mapping
 *   chat_id
 *   version
 *   responded_at
 *
 * Mode: Run Once for All Items
 */

const input = $('Regex detect 2').first().json;
const editor = $('Prepare Editor Input').first().json;

const text = String(input.text ?? '');

if (!text.trim()) {
  throw new Error('PHI_GATE_EMPTY_INPUT');
}

// Read Presidio detections.
let ents = $('Presidio analyze 2')
  .all()
  .map(item => item.json)
  .flatMap(json => Array.isArray(json) ? json : [json])
  .filter(e =>
    e &&
    Number.isInteger(e.start) &&
    Number.isInteger(e.end)
  );

const KEEP = new Set([
  'PERSON',
  'PHONE_NUMBER',
  'EMAIL_ADDRESS',
  'LOCATION',
  'US_SSN',
  'US_PASSPORT',
  'US_DRIVER_LICENSE',
  'IP_ADDRESS',
  'DATE_TIME'
]);

// Preserve recognized radiology descriptors.
const clinicalDescriptors = new Set([
  'lobulated',
  'irregular',
  'smooth',
  'ill-defined',
  'hypoechoic',
  'hyperechoic',
  'isoechoic',
  'anechoic',
  'taller-than-wide',
  'wider-than-tall',
  'solid',
  'spongiform',
  'punctate echogenic foci'
]);

function isClinicalDescriptor(entity) {
  if (entity.entity_type !== 'PERSON') return false;

  const value = text
    .slice(entity.start, entity.end)
    .trim()
    .toLowerCase();

  if (!clinicalDescriptors.has(value)) return false;

  const before = text.slice(
    Math.max(0, entity.start - 60),
    entity.start
  );

  return /(?:margins?|echogenicity|composition|shape|echogenic foci)\s*:\s*$/i
    .test(before);
}

ents = ents.filter(e =>
  KEEP.has(e.entity_type) &&
  Number(e.score) >= 0.5 &&
  !isClinicalDescriptor(e)
);

// Detect structured identifiers missed by Presidio.
function add(regex, type, group = 0) {
  for (const match of text.matchAll(regex)) {
    const value = match[group];

    if (!value) continue;

    const offset = match[0].lastIndexOf(value);
    const start = match.index + offset;

    ents.push({
      entity_type: type,
      start,
      end: start + value.length,
      score: 1
    });
  }
}

add(/\b[23]\d{13}\b/g, 'NATIONAL_ID');

add(
  /\bMRN\s*[:#]?\s*(\d{5,})\b/gi,
  'MRN',
  1
);

add(
  /\b(?:DOB|date\s+of\s+birth|birth\s+date)\s*:\s*(\d{1,2}[/-]\d{1,2}[/-]\d{4}|\d{4}-\d{2}-\d{2})/gi,
  'DOB',
  1
);

add(
  /\b(?:patient\s+name|patient's\s+name)\s*:\s*([^\n\r,;]+)/gi,
  'PERSON',
  1
);

// Resolve overlaps.
ents = ents.filter(e =>
  e.start >= 0 &&
  e.end <= text.length &&
  e.end > e.start
);

ents.sort((a, b) =>
  Number(b.score) - Number(a.score) ||
  (b.end - b.start) - (a.end - a.start)
);

const kept = [];

for (const entity of ents) {
  const overlaps = kept.some(existing =>
    entity.start < existing.end &&
    entity.end > existing.start
  );

  if (!overlaps) {
    kept.push(entity);
  }
}

kept.sort((a, b) => a.start - b.start);

// Replace detected identifiers.
let out = '';
let cursor = 0;

const mapping = {};
const counters = {};
const seen = {};

for (const entity of kept) {
  const value = text.slice(entity.start, entity.end);
  const type = entity.entity_type;

  const key = type + '|' + value.toLowerCase();

  if (!seen[key]) {
    counters[type] = (counters[type] || 0) + 1;

    const placeholder = `[${type}_${counters[type]}]`;

    seen[key] = placeholder;
    mapping[placeholder] = value;
  }

  out += text.slice(cursor, entity.start);
  out += seen[key];

  cursor = entity.end;
}

out += text.slice(cursor);

// Separate the report and feedback using the
// original known section boundaries.
const reportHeader = 'CURRENT REPORT:\n';
const feedbackHeader = '\nDOCTOR REQUESTED EDITS:\n';

if (!out.startsWith(reportHeader)) {
  throw new Error('INVALID_REPORT_SECTION');
}

const separatorIndex = out.lastIndexOf(feedbackHeader);

if (separatorIndex < reportHeader.length) {
  throw new Error('INVALID_FEEDBACK_SECTION');
}

const safeReport = out.slice(
  reportHeader.length,
  separatorIndex
).trim();

const safeFeedback = out.slice(
  separatorIndex + feedbackHeader.length
).trim();

if (!safeReport || !safeFeedback) {
  throw new Error('EMPTY_SANITIZED_REPORT_OR_FEEDBACK');
}

// Return sanitized data.
return [{
  json: {
    userPrompt: out,

    current_report: safeReport,
    original_report: safeReport,
    doctor_feedback: safeFeedback,

    mapping,

    chat_id: editor.chat_id ?? null,
    version: editor.version ?? 1,
    responded_at: editor.responded_at ?? null
  }
}];

const old = $('Prepare Editor Input').last().json;
const output = String($json.output ?? $json.text ?? '').trim();

if (!output) {
  throw new Error('AI editor returned an empty report');
}

return [{
  json: {
    case_id: old.case_id,
    chat_id: old.chat_id,
    current_report: output,
    doctor_feedback: old.doctor_feedback,
    version: (Number(old.version) || 1) + 1,
    status: 'PENDING_DOCTOR_REVIEW',
    updated_at: new Date().toISOString()
  }
}];

// Latest report version, read from upstream nodes (no static data needed)
function latestSession() {
  try {
    if ($('Save Repeat Version').isExecuted) return $('Save Repeat Version').last().json;
  } catch (e) {}
  try {
    if ($('Save New Report Version').isExecuted) return $('Save New Report Version').last().json;
  } catch (e) {}
  return $('TEST DATA - Initialize HITL Session').first().json;
}

const s = latestSession();

const raw = $input.first().json;
const data = raw.data ?? raw;
let feedback = data['Describe your requested edits'] ?? data.text ?? raw.text ?? '';
if (!String(feedback).trim() && data && typeof data === 'object') {
  const firstText = Object.values(data).find(v => typeof v === 'string' && v.trim());
  if (firstText) feedback = firstText;
}
feedback = String(feedback).trim();

if (!feedback) {
  throw new Error('Empty doctor feedback. Raw input from form node: ' + JSON.stringify(raw));
}

return [{
  json: {
    case_id: s.case_id,
    chat_id: s.chat_id,
    current_report: s.current_report,
    original_report: s.current_report,
    doctor_feedback: feedback,
    version: s.version
  }
