/**
 * RADRAFT — REGEX DETECT 3
 * Repeated doctor-requested adjustments.
 *
 * Input: Prepare Next Editor Input
 * Output: request_id, text, spans, chat_id, version
 */

const patterns = {
  SSN: /\b\d{3}-\d{2}-\d{4}\b/g,
