  MRN: /\bMRN[:# ]?\s?\d{6,10}\b/gi,
  DATE: /\b\d{1,2}[/-]\d{1,2}[/-]\d{2,4}\b/g,
  IP: /\b(?:\d{1,3}\.){3}\d{1,3}\b/g,
  URL: /\bhttps?:\/\/[^\s]+/g,
  ACCOUNT: /\bACCT[:# ]?\s?\d{6,12}\b/gi
};

const results = [];

for (const item of $input.all()) {
  const json = item.json;

  const currentReport = String(
    json.current_report ?? ''
  );

  const doctorFeedback = String(
    json.doctor_feedback ?? ''
  );

  if (!currentReport.trim()) {
    throw new Error(
      'REGEX_DETECT_3: Current report is missing.'
    );
  }

  if (!doctorFeedback.trim()) {
    throw new Error(
      'REGEX_DETECT_3: Doctor feedback is missing.'
    );
  }

  // Combine report and feedback for PHI detection.
  const text = [
    'CURRENT REPORT:',
    currentReport,
    '',
    'DOCTOR REQUESTED EDITS:',
    doctorFeedback
  ].join('\n');

  const spans = [];

  for (const [type, pattern] of Object.entries(patterns)) {
    const regex = new RegExp(
      pattern.source,
      pattern.flags
    );

    for (const match of text.matchAll(regex)) {
      spans.push({
        type,
        start: match.index,
        end: match.index + match[0].length,
        value: match[0],
        source: 'regex'
      });
    }
  }

  spans.sort((a, b) =>
    a.start - b.start ||
    b.end - a.end
  );

  results.push({
    json: {
      request_id: String(
        json.request_id ?? $execution.id
      ),
      text,
      spans,
      chat_id: json.chat_id ?? null,
      version: json.version ?? 1
    }
  });
}

return results;

/**
