  {
    name: 'Data from Workflow 4',
    data: source
  }
];

let selected = null;
let approvedReport = null;

for (const candidate of candidates) {
  if (!candidate.data) continue;

  const report = [
    candidate.data.current_report,
    candidate.data.approved_report,
    candidate.data.draft_report,
    candidate.data.final_report,
    candidate.data.report,
    candidate.data.output
  ].find(value =>
    typeof value === 'string' &&
    value.trim()
  );

  if (report) {
    selected = candidate;
    approvedReport = report;
    break;
  }
}

if (!approvedReport) {
  throw new Error(
    'APPROVAL_ERROR: No report found. Check Data from Workflow 4.'
  );
}

// 4. Obtain Telegram chat ID.
const chatId =
  selected.data.chat_id ??
  source.chat_id ??
  null;

if (chatId == null || chatId === '') {
  throw new Error('APPROVAL_ERROR: Missing chat ID.');
}

// 5. Preserve actual approval timestamp.
const approvedAt =
  data.respondedAt ??
  data.approved_at ??
  null;

if (
  !approvedAt ||
  Number.isNaN(Date.parse(approvedAt))
) {
  throw new Error(
    'APPROVAL_ERROR: Invalid approval timestamp.'
  );
}

// 6. Preserve report version.
const version = Number(
  selected.data.version ??
  source.version ??
  1
);

if (!Number.isInteger(version) || version < 1) {
  throw new Error(
    'APPROVAL_ERROR: Invalid version.'
  );
}

// 7. Return approved report.
return [{
  json: {
    chat_id: String(chatId),

    current_report: approvedReport,
    approved_report: approvedReport,

    doctor_name:
      source.doctor_name ?? null,

    patient_metadata_mapping:
      source.patient_metadata_mapping ?? {},

    patient_metadata_rest:
      source.patient_metadata_rest ?? {},

    report_id:
      source.report_id ?? null,

    session_id:
      source.session_id ?? null,

    version,
    approved_at: approvedAt,
    status: 'approved',

    report_source: selected.name
  }
}];
